(window.GIM_TS=window.GIM_TS||{})["Keritot.2"]={"from":48,"a":[["\u0003למפשטיה\u0004 \u0005[לפתור אותה]\u0006 \u0003לא מ\u0004דברי \u0003רב דימי,\u0004 שלמד ממה שנאמר בשעיר הפנימי: \"ומפשעיהם לכל חטאתם\" (ויקרא טז, טז), \u0003ולא מ\u0004דברי \u0003אביי\u0004 שלמד ממה שנאמר בשעיר המשתלח: \"ואת פשעיהם לכל חטאתם\" (שם כא),","\u0003אלא מהא\u0004 \u0005[מזו]\u0006 שאמר ר' אלעזר לענין אשם תלוי: \"מכל חטאתיכם לפני ה' תטהרו\" (שם ל), \u0003חטא שאין מכיר בו אלא המקום יום הכפורים מכפר, ומינה\u0004 \u0005[וממנה]\u0006 תסיק בדרך השלילה: דווקא \u0003חטא שאין מכיר בו אלא המקום הוא\u0004 החטא שיום \u0003הכפורים מכפר, אבל\u0004 חטא \u0003דידע בה\u0004 \u0005[ש\u0006החוטא \u0005יודע בו]\u0006 — \u0003לא מכפר.\u0004","\u0003ואמר רב תחליפא אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב הונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: חייבי מלקיות שעבר עליהן יום הכפורים\u0004 — \u0003חייב,\u0004 אינם נפטרים מעונש המלקות. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003מחייבי חטאות ואשמות ודאין\u0004 שחייבים להביא קרבן?","ומשיבים, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בחייבי חטאות ואשמות\u0005]\u0006 — \u0003ממונא\u0004 \u0005[\u0006חיוב \u0005ממון]\u0006 \u0003הוא,\u0004 שצריך להביא קרבן לה', ועל הממון שהוא חייב אין יום הכיפורים פוטרו, \u0003אבל הכא\u0004 \u0005[כאן,\u0006 במלקות\u0005]\u0006 \u0003דגופא\u0004 \u0005[\u0006שעונש \u0005של הגוף]\u0006 \u0003הוא\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ילקה לאחר יום הכיפורים, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין הדבר כן.","ומקשים: כיצד אומר רבא שיום הכיפורים אינו פוטר ממלקות? \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 ששעיר המשתלח של יום הכיפורים מכפר על \u0003הודע ולא הודע, עשה ולא תעשה,\u0004 ועל מצות לא תעשה יש חיוב מלקות!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא דאתרו ביה\u0004 \u0005[זה שהתרו בו]\u0006 ובכך נתחייב מלקות — אין יום הכיפורים מכפר עליו לגמרי עד שילקה, \u0003הא דלא אתרו ביה\u0004 \u0005[זה שלא התרו בו]\u0006 ואין מלקים אותו — יום הכפורים מכפר עליו.","ושבים למה שאמרנו, שאין מביאים אשם תלוי לאחר יום הכיפורים, מפני שיום זה מכפר על חטא שאין מכיר בו אלא המקום. ומקשים: \u0003אלא מעתה,\u0004","\u0003ספק יולדת שעבר עליה יום הכפורים לא תייתי\u0004 \u0005[תביא]\u0006 חטאת, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כפר עליה יום הכפורים,\u0004 שהרי מדובר ב\u0003חטא שאין מכיר בו אלא המקום הוא,\u0004 שהרי המקום יודע אם היא חייבת חטאת! \u0003אמר רב הושעיא:\u0004 אמר הכתוב בענין יום הכיפורים \u0003\"לכל חטאתם\"\u0004 (ויקרא טז, כא), \u0003ולא לכל טומאתם,\u0004 והיולדת אינה מביאה קרבן על חטא, אלא לטהרה, כדי להתירה באכילת קדשים.","ומקשים: \u0003ול\u0004דעת ר' \u0003שמעון בן יוחי\u0004 שאמר: \u0003יולדת חוטאת היא, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: גם לדעת ר' שמעון, \u0003יולדת כי קא מייתי\u0004 \u0005[כאשר מביאה]\u0006 \u0003קרבן\u0004 — \u0003לאישתרויי\u0004 \u0005[להתיר אותה]\u0006 \u0003באכילת קדשים הוא,\u0004 שהוא גמר טהרתה, \u0003ולא לכפרה מתיא\u0004 \u0005[היא מביאה],\u0006 ולענין זה אין יום הכיפורים מועיל.","\u0003אמר רב אשי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כעין זה במשנתנו: \u0003האשה שיש עליה חטאת העוף ספק,\u0004 שמא ילדה, \u0003ועבר עליה יום הכפורים\u0004 — \u0003חייבת להביא לאחר יום הכפורים, מפני שמכשרתה לאכול בזבחים,\u0004 משמע שהטעם הוא דווקא משום הטהרה, ולא משום החטא.","ומקשים עוד: \u0003אלא מעתה, ספק מצורע\u0004 שחייב להביא קרבן לטהרתו, \u0003שעבר עליו יום הכפורים, לא מייתי\u0004 \u0005[יביא]\u0006 קרבן, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003עבר עליה יום הכפורים,\u0004 שחטא \u0003שאין מכיר בו אלא המקום הוא,\u0004 שרק הקדוש ברוך הוא יודע אם הוא טמא! \u0003אמר ר' אושעיא:\u0004 הרי נאמר \u0003\"לכל חטאתם\"\u0004 — \u0003ולא לכל טומאתם,\u0004 והקרבן לטהרתו הוא בא.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן: על שבעה דברים נגעים באים,\u0004 משמע שהצרעת באה על חטא מסויים, ואם כן ראוי לו להביא קרבן לכפרה! ומשיבים: על כל פנים \u0003מצורע כי מייתי לאו לכפרה מייתי\u0004 \u0005[כאשר מביא קרבן, לא לכפרה הוא מביא אותו],\u0006 \u0003אלא לאישתרויי\u0004 \u0005[להתירו]\u0006 \u0003באכילת קדשים הוא\u0004 שמביא, ולכך לא מועיל יום הכיפורים.","ועוד שואלים: \u0003אלא מעתה, ספק נזיר\u0004 כלומר, נזיר שספק נטמא במת, וצריך להביא קרבן לטהרתו, במקרה \u0003שעבר עליו יום הכפורים לא מייתי\u0004 \u0005[יביא]\u0006 \u0003קרבן, דהא\u0004 \u0005[שהרי]\u0006 \u0003כפר יום הכפורים,\u0004 שחטא \u0003שאין מכיר בו אלא המקום הוא! אמר ר' אושעיא:\u0004 נאמר \"\u0003לכל חטאת\"\u0004 — \u0003ולא לכל טומאה.\u0004","ושואלים: ולדעת ר' \u0003אלעזר בן הקפר\u0004 שאמר: \u0003נזיר חוטא הוא,\u0004 שציער עצמו מן היין, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003נזיר כי קא מייתי\u0004 \u0005[כאשר הוא מביא]\u0006 \u0003קרבן, לאו\u0004 \u0005[לא]\u0006 \u0003לכפרה מייתי\u0004 \u0005[הוא מביא],\u0006 אלא \u0003אלא לאשתרויי\u0004 \u0005[להתיר אותו]\u0006 \u0003באכילת קדשים הוא,\u0004 ולכך לא מועיל יום הכפורים.","ומקשים עוד: \u0003אלא מעתה, ספק סוטה\u0004 כלומר, סוטה, שראוה שנסתרה, וספק שמא קלקלה, במקרה \u0003שעבר עליה יום הכפורים לא תייתי\u0004 \u0005[תביא]\u0006 מנחתה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כפר עלה\u0004 \u0005[עליה]\u0006 \u0003יום הכפורים,\u0004 שחטא \u0003שאינו מכיר בו אלא המקום\u0004 הוא! \u0003אמר ר' הושעיא:\u0004 נאמר בכפרת יום הכיפורים: \u0003\"לכל חטאתם\"\u0004 — \u0003ולא לכל טומאתם,\u0004 ועל הטומאה אין שייכת כפרה.","אמר אביי: אין זה חטא שרק המקום מכיר בו, שהרי ה\u0003בועל מכיר בו. רבא אמר:\u0004 מעיקרו של דבר אין להקשות, כי \u0003סוטה כי מתייא\u0004 \u0005[כאשר היא מביאה]\u0006 את המנחה \u0003לברר עון קא אתיא\u0004 \u0005[היא מביאה]\u0006 כדי לברר אם נטמאה, ולא לשם כפרתה.","ועוד שואלים: \u0003אלא מעתה,\u0004 שחטא שאין מכיר בה אלא המקום יום הכיפורים מכפר, \u0003עגלה ערופה שעבר עליה יום הכפורים\u0004 לא יביאו, שהרי אין ידוע מי הרוצח! \u0003אמר אביי: הורג\u0004 עצמו \u0003מכיר\u0004 בחטא, הוא יודע שהרג. \u0003רבא אמר, אמר קרא\u0004 \u0005[המקרא]: \"\u0006\u0003ולארץ לא יכפר לדם אשר שפך בה\u0004 כי אם בדם שופכו\" (במדבר לה, לג), משמע שאין כפרה אלא בעגלה הערופה, או בדמו של ההורג.","\u0003רב פפא אמר, אמר קרא\u0004 \u0005[המקרא]\u0006 בדברי הכהנים על העגלה הערופה: \u0003\"כפר לעמך ישראל\u0004 אשר פדית ה'\" (דברים כא, ח), ומכאן ש\u0003ראויה כפרה זו שתכפר\u0004 למפרע גם \u0003על יוצאי מצרים\u0004 (שפדה ה'), על כל ספק שפיכות דמים משיצאו ישראל ממצרים, ומכאן שימי הכיפורים שעברו מאז עדיין לא כיפרו עליהם.","ושואלים: \u0003השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]:\u0006 \u0003חטא שאין מכיר בו אלא המקום יום הכפורים מכפר, אימא\u0004 \u0005[אמור]:\u0006 \u0003כי מתיידע ליה בתר\u0004 \u0005[כאשר נודע לו\u0006 חטאו רק \u0005אחרי]\u0006 \u0003יום הכפורים נמי לא מייתי\u0004 \u0005[גם כן לא יביא]\u0006 \u0003חטאת! אמר ר' זעירא: לא מצית אמרת\u0004 \u0005[אינך יכול לומר\u0006 זאת\u0005], דכתיב קרא\u0006 \u0005[שנכתבה במקרא]\u0006 \u0003ידיעה גבי\u0004 \u0005[אצל]\u0006 \u0003חטאת\u0004 יחיד \u0003וגבי\u0004 \u0005[אצל]\u0006 חטאת \u0003נשיא וגבי\u0004 \u0005[ואצל]\u0006 חטאת \u0003צבור,\u0004 ולא הוצרכנו לשלושתם, ומייתור הכתובים אתה למד כי כל שנודע לו החטא, גם לאחר יום הכיפורים — חייב להביא חטאתו. ודוחים: לא ניתן ללמוד מכך, מפני שכולם \u0003צריכי\u0004 \u0005[צריכים\u0006 הם\u0005]\u0006 כל אחד לגופו, ללמד שמביאים קרבן רק על חטא ידוע, ולא על הספק.","\u0003דאי כתב קרא\u0004 \u0005[שאם היה כותב המקרא]\u0006 ידיעה רק לגבי חטאת היחיד — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כולהון\u0004 \u0005[כולם,\u0006 נשיא וציבור\u0005] מיחיד לא אתאן\u0006 \u0005[באים,\u0006 נלמדים\u0005]\u0006 מפני \u0003דאיכא למיפרך\u0004 \u0005[שיש מקום לפרוך]\u0006 את ההשוואה ולומר: \u0003מה ליחיד,\u0004 שהוא קל, \u0003שכל קרבנו\u0004 בחטאת אינו אלא \u0003נקבה,\u0004 כשבה או שעירה, ואין ללמוד ממנו לנשיא שמביא שעיר על שגגתו, ולציבור שמביאים פר.","ואומרים: עדיין יש ייתור, \u0003נכתוב\u0004 \u0005[שיכתוב]\u0006 ענין זה לגבי \u0003נשיא ונייתי הנך\u0004 \u0005[ויבואו ו\u0006ילמדו \u0005אלה,\u0006 יחיד וציבור\u0005] מנשיא!\u0006","ודוחים: \u0003יחיד מנשיא לא אתי\u0004 \u0005[בא,\u0006 נלמד\u0005],\u0006 מפני \u0003דאיכא למיפרך\u0004 \u0005[שיש מקום לפרוך]:\u0006 \u0003מה לנשיא,\u0004 שדינו קל, \u0003שכן אין\u0004 בו קרבן חטאת \u0003בשמיעת קול\u0004 (כשנשבע לשקר שאינו יודע עדות) לפי שהמלך אינו מעיד, ולא שייך בו עוון זה, \u0003תאמר ביחיד שכן ישנו בשמיעת קול! ו\u0004כן","\u0003צבור מנשיא לא אתי\u0004 \u0005[בא]\u0006 מפני \u0003דאיכא למיפרך\u0004 \u0005[שיש מקום לפרוך]\u0006 את ההשוואה ולומר: \u0003מה לנשיא שכן\u0004 יש \u0003בקרבנו נקבה,\u0004 שמביא עז אם חטא בשגגת עבודה זרה, ואילו קרבן חטאת של ציבור אינו אלא בזכרים!","ואומרים: עדיין יש כאן ייתור, \u0003נכתוב\u0004 \u0005[שיכתוב]\u0006 ידיעה לגבי \u0003צבור,\u0004 ויילמדו \u0003יחיד ונשיא מינה\u0004 \u0005[ממנו]!\u0006 ודוחים: \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך]\u0006 ולומר: \u0003מה לצבור\u0004 שיש בהם צד קל, \u0003שכן אין חייבין\u0004 חטאת \u0003אלא על העלם דבר עם שגגת מעשה,\u0004 שטעו הסנהדרין בהוראה ועשה הקהל בשגגה על פיהם, ואילו יחיד ונשיא חייבים בשגגת עצמם, ואם כן אין בכך יתור.","ואומרים: ועדיין יש מקום לומר שאחת מן הידיעות שנזכרו בכתוב מיותרת, שכן גם אם \u0003מחדא ידיעה לא אתיא\u0004 \u0005[מידיעה אחת אי אפשר ללמוד]\u0006 על שני המקרים האחרים, \u0003תיתי חדא ידיעה מתרתי\u0004 \u0005[שתבוא,\u0006 תילמד \u0005ידיעה אחת משתים],\u0006 שתיכתב ידיעה רק בשני מקרים, והשלישי יילמד ביניהם, כיצד? \u0003לא נכתוב\u0004 \u0005[שלא יכתוב]\u0006 \u0003ידיעה\u0004 לגבי \u0003יחיד ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד\u0005] מנשיא וצבור!\u0006 ודוחים: \u0003איכא\u0004","\u0003למיפרך\u0004 \u0005[יש מקום לפרוך]\u0006 את ההשוואה ולומר: \u0003מה לנשיא וצבור,\u0004 שיש בהם צד קל, \u0003שכן אינן ב\u0004קרבן על \u0003שמיעת קול, תאמר ביחיד שישנו בשמיעת קול!\u0004","ואומרים: \u0003לא נכתוב קרא\u0004 \u0005[שלא יכתוב המקרא]\u0006 \u0003ידיעה\u0004 לגבי \u0003צבור ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד] \u0003מידיעה\u0004 של \u0003יחיד ונשיא!\u0004 ודוחים: \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך]:\u0006 \u0003מה ליחיד ונשיא שכן יש בקרבן\u0004 חטאתם \u0003נקבה, תאמר בצבור שאין בקרבן\u0004 חטאתם \u0003נקבה!\u0004","ואומרים: מכל מקום יש כאן יתור, \u0003לא נכתוב\u0004 \u0005[שלא יכתוב\u0006 המקרא\u0005]\u0006 ידיעה ל\u0003גבי נשיא ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד\u0005]\u0006\u0003 מידיעה\u0004 של \u0003יחיד וצבור!\u0004 והרי במקרה זה, \u0003מאי פרכת\u0004 \u0005[מה אתה יכול לפרוך]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שדינם של ציבור קל יותר \u0003משום\u0004 ש\u0003אינן בשמיעת הקול\u0004 — \u0003יחיד יוכיח, (דאינו) [דישנו] בשמיעת הקול,\u0004 ומכל מקום צריך ידיעה כדי לחייבו,","\u0003ואי\u0004 \u0005[ואם]\u0006 תאמר שיחיד קל יותר \u0003משום\u0004 ש\u0003יש בכל קרבנו\u0004 של יחיד \u0003נקבה\u0004 — \u0003צבור יוכיח,\u0004 ש\u0003אין בקרבנן נקבה,\u0004 ובכל זאת, \u0003עד דאית להון\u0004 \u0005[שיש להם]\u0006 \u0003ידיעה לא מחייב\u0004 \u0005[אינם מתחייבים],\u0006 אם כן \u0003למה לי דכתיב\u0004 \u0005[שנכתבה]\u0006 \u0003ידיעה גבי נשיא?\u0004","\u0003אם אינו ענין לגופיה\u0004 \u0005[לגופו],\u0006 \u0003דהא אתיא\u0004 \u0005[שהרי באה,\u0006 נלמדה\u0005] מיחיד וצבור\u0006 — \u0003תנהו ענין להיכא דמתיידע ליה בתר\u0004 \u0005[למקום שנודע לו\u0006 חטאו רק \u0005אחר]\u0006 \u0003יום הכפורים, דמייתי\u0004 \u0005[שמביא]\u0006 \u0003חטאת.\u0004","\u0003אביי אמר: אי דלא כתיב\u0004 \u0005[אם\u0006 במקרה \u0005שלא היה כתוב]\u0006 \u0003ידיעה גבי\u0004 \u0005[אצל]\u0006 \u0003נשיא, מיחיד וצבור לא אתי\u0004 \u0005[בא],\u0006 לא יכול היה להילמד, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש מקום לפרוך]\u0006 ולומר: \u0003מה ליחיד וצבור שכן אין עשויין להשתנות,\u0004 שקרבנם קבוע, \u0003תאמר\u0004"],["\u0003בנשיא שעשוי להשתנות,\u0004 שאם הוא יורד מנשיאותו דינו כיחיד!","\u0003אלא אמר אביי, מהכא\u0004 \u0005[מכאן]\u0006 למדים שאין יום הכיפורים מכפר על חייבי חטאות: \u0003מכדי\u0004 \u0005[הרי]\u0006 חטאת הציבור, הנשיא והיחיד, בגזירה שווה \u0003\"מצו‍ת\" \"מצו‍ת\" ילפי מהדדי\u0004 \u0005[למדים זה מזה],\u0006 שבשלושתם נזכר ביטוי זה, ו","\u0003כיון דילפי מהדדי\u0004 \u0005[שהם לומדים זה מזה],\u0006 אם כן, \u0003למה לי דכתיב\u0004 \u0005[שייכתבו]\u0006 \u0003שלש ידיעות, גבי\u0004 \u0005[אצל]\u0006 \u0003יחיד וגבי\u0004 \u0005[ואצל]\u0006 \u0003נשיא וגבי\u0004 \u0005[ואצל]\u0006 \u0003צבור? אם אינו ענין לגופיהן\u0004 ללמד שאינן באות אלא על ידיעה ודאית, \u0003דהא גמרי להן\u0004 \u0005[שהרי למדים הם]\u0006 בגזירה שווה של \"\u0003מצו‍ת\" \"מצו‍ת\"\u0004 — \u0003תנהו ענין\u0004 ללמד כי \u0003היכא דמתיידע ליה בתר\u0004 \u0005[\u0006גם ב\u0005מקום שנודע לו\u0006 חטאו \u0005אחר]\u0006 \u0003יום הכיפורים הוא דמייתי\u0004 \u0005[שמביא]\u0006 \u0003חטאת.\u0004","ושואלים, לפי זה, \u0003אימא\u0004 \u0005[אמור]:\u0006 דווקא \u0003כי מתיידע ליה בתר\u0004 \u0005[כאשר נודע לו\u0006 חטאו \u0005אחר]\u0006 \u0003יום כפורים הוא דמייתי\u0004 \u0005[שמביא]\u0006 \u0003חטאת, משום\u0004 שיום \u0003הכפורים לאו על הדין חטא קא אתי\u0004 \u0005[לא על חטא\u0006 מסוים \u0005זה\u0006 הוא \u0005בא]\u0006 לכפר, \u0003אבל\u0004 מי שהביא \u0003אשם תלוי\u0004 כשהיה לו ספק אם חטא, \u0003דעל הדין חטא קאתי\u0004 \u0005[שעל חטא זה\u0006 הוא \u0005בא]\u0006 — \u0003אימא הכי נמי דמיכפר\u0004 \u0005[אמור גם כן שמתכפר],\u0006 \u0003דכי מתיידע לבתר דקא מייתי\u0004 \u0005[שכאשר נודע לו\u0006 החטא \u0005אחרי שהביא]\u0006 \u0003אשם תלוי\u0004 — \u0003לא מייתי\u0004 \u0005[אינו צריך להביא]\u0006 \u0003חטאת!\u0004","\u0003אמר רבא,\u0004 כנגד זה \u0003אמר קרא\u0004 \u0005[המקרא]\u0006\u0003: \"או הודע אליו\u0004 חטאתו אשר חטא\" (ויקרא ד, כח) — \u0003מכל מקום,\u0004 בכל מקרה שנודע לו. ושואלים: \u0003השתא דאמר\u0004 \u0005[עכשיו שאתה אומר]:\u0006 \u0003כי מתיידע ליה מייתי\u0004 \u0005[כאשר נודע לו\u0006 בכל זמן \u0005מביא]\u0006 \u0003חטאת, אשם תלוי למה\u0004 הוא \u0003בא? אמר ר' זירא:\u0004 לומר, \u0003שאם מת\u0004 בינתיים, לפני שנודע לו חטאו — \u0003מת בלא עון. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא:\u0004 אם \u0003מת,\u0004 הרי \u0003מיתה ממרקת\u0004 את העוון, ובזה מתכפר לו, ואינו צריך אשם תלוי! \u0003אלא אמר רבא:\u0004 טעם הדבר שמביא אשם תלוי — כדי \u0003להגן עליו\u0004 בינתיים \u0003מן הייסורים\u0004 עד שיביא חטאתו.","שנינו במשנה: \u0003חטאת העוף\u0004 של יולדת \u0003הבא על הספק,\u0004 שאינה נאכלת על ידי הכהנים, אם משנמלקה נודע לה שילדה בוודאות — תיקבר. \u0003אמר רב: וכיפר,\u0004 כלומר, יצאה בה ידי חובתה לאחר שיזה מדמה וימצה אותו על קיר המזבח. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם היא מכפרת — תיאכל לכהנים כדין חטאת עוף ודאית, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003תקבר?\u0004","ומשיבים: \u0003לפי שאינה משתמרת,\u0004 שכיוון שבאה מתחילה על הספק, שלא על מנת להיאכל על ידי הכהנים, הכהן מסיח דעתו ממנה, ושמא נטמאה. ושואלים: \u0003אימת\u0004 \u0005[מתי]\u0006 \u0003לא משתמרת? אי מעיקרא\u0004 \u0005[אם מתחילה]\u0006 לפני המליקה — \u0003חיה הויא\u0004 \u0005[היתה],\u0006 והחי אינו מקבל טומאה! \u0003אי\u0004 \u0005[אם]\u0006 \u0003לבסוף,\u0004 אחר שנמלקה — \u0003קמנטר לה\u0004 \u0005[הרי הוא משמר אותה]!\u0006","\u0003אלא מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003בנודע לה\u0004 לאשה שלא \u0003ילדה\u0004 ולד המצריך קרבן, \u0003ובדין הוא\u0004 שהחטאת היתה צריכה להיות \u0003מותרת בהנאה,\u0004 שהרי נתברר שעוף זה חולין הוא, \u0003ומאי\u0004 \u0005[ומה]\u0006 טעם \u0003תקבר? מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 שמא ילמדו מכאן שכל חטאת העוף הבאה על הספק מותרת בהנאה.","\u0003וכי איתמר\u0004 \u0005[וכאשר נאמרו]\u0006 דברי \u0003רב\u0004 שכיפרה, הרי זה \u0003על\u0004 מה ששנינו בפרק הקודם (כב,ב): \u0003האשה שהביאה חטאת העוף בספק, אם עד שלא נמלקה נודע לה שילדה ודאי\u0004 — \u0003תעשה ודאי, שממין שהביאה על לא הודע,\u0004 כלומר על הספק — \u0003מביאה על הודע\u0004 גם על לידת ודאי.","\u0003אם משנמלקה\u0004 חטאת זו \u0003נודע\u0004 לה \u0003שילדה\u0004 ודאי — על כך \u0003אמר רב:\u0004 גם במקרה זה \u0003מזה דמה ומוצה\u0004 (ממצה) את \u0003דמה\u0004 על קיר המזבח, \u0003וכפרה\u0004 כלומר, יצאה ידי חובתה, ו\u0003מותרת באכילה\u0004 לכהנים. \u0003ר' יוחנן אמר:\u0004 במקרה זה, אף שמזה וממצה את דמה, וכיפרה — \u0003אסורה באכילה,\u0004 ומדוע? \u0003גזירה שמא יאמרו:\u0004 כל \u0003חטאת העוף הבאה על הספק נאכלת.\u0004","ומעירים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 בברייתא \u0003כותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב: חטאת העוף הבאה על הספק, אם משנמלקה נודע שילדה ודאי\u0004 — הרי הוא \u0003מזה דמה ומוצה דמה, וכפרה,\u0004 ו\u0003מותרת באכילה.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה ברייתא\u0006 גם כשיטתו] של ר' \u0003יוחנן: חטאת העוף הבאה על הספק, אם עד שלא נמלקה נודע לה שלא ילדה\u0004 — \u0003תצא\u0004 החטאת \u0003לחולין, או תמכר לחברתה\u0004 שחייבת בחטאת. \u0003אם עד שלא נמלקה נודע לה שילדה ודאי\u0004 — \u0003תעשה\u0004 אותה \u0003ודאי, שממין שמביאה על לא הודע מביאה על הודע.\u0004","\u0003אם משנמלקה נודע שילדה\u0004 ודאי — מזה וממצה את דמה, וכיפרה, ואולם אסורה באכילה. אבל אם כבר נתמצה דמה — \u0003אסורה אפילו בהנאה,\u0004 וכדין כל חטאת העוף הבאה על הספק. שכיון \u0003ש\u0004חטאת זו \u0003על הספק באה מתחלתה,\u0004 הרי כבר \u0003כפרה ספיקה והלכה לה,\u0004 כלומר, כל מעשיה נעשו לשם מה שהופרשה, על הספק, וכך נוהגים בה.","\u0003המפריש שני סלעים ל\u0004קנות בהם קרבן \u0003אשם\u0004 (שמן התורה צריך להקריב איל בשווי שני סלעים לפחות), \u0003ולקח\u0004 (קנה) \u0003בהן שני אילים ל\u0004שם \u0003אשם, אם היה אחד מהן יפה\u0004 (שווה) כעת \u0003שתי סלעים,\u0004 אלא שקנה אותו בזול — \u0003יקרב\u0004 איל זה \u0003לאשמו, והשני,\u0004 שקנה גם כן בדמי האשם, אינו יוצא לחולין, אלא \u0003ירעה עד שיסתאב\u0004 (שיפול בו מום), \u0003וימכר ויפלו דמיו לנדבה,\u0004 לקרבן עולה של ציבור.","אם \u0003לקח בהן\u0004 בשני סלעים אלו, \u0003שני אילים ל\u0004שם \u0003חולין,\u0004 ונמצא שמעל בהקדש בשני סלעים, ועליו להקריב אשם מעילות בשווי שני סלעים, וכן לשלם להקדש שני סלעים שמעל בהם בתוספת חומש (כלומר, בתוספת רבע, שהוא חומש מן הסכום הכולל), וביחד עשרה זוזים, שבכל סלע ארבעה זוזים. אם \u0003אחד\u0004 משני האילים שקנה \u0003יפה שתי סלעים ואחד יפה\u0004 שווה \u0003עשרה זוז\u0004 — \u0003היפה שתי סלעים יקרב לאשמו,\u0004 כלומר, לאשם מעילות, \u0003והשני\u0004 השווה עשרה זוז — \u0003למעילתו\u0004 כלומר, לשם קרבן האשם שהיה צריך להביא מתחילה בשני סלעים, בתוספת חומש.","אם בשני הסלעים שהפריש מתחילה לשם אשם קנה שני אילים, \u0003אחד לאשם ואחד לחולין,\u0004 ונמצא שמעל בסלע שקנה בו איל לחולין, \u0003אם היה\u0004 האיל \u0003של אשם יפה\u0004 עכשיו \u0003שתי סלעים\u0004 — \u0003יקרב לאשמו,\u0004 כלומר, לאשם שנתחייב בו בתחילה, \u0003והשני\u0004 שקנה לשם חולין, אם היה שווה שני סלעים יקרב \u0003ל\u0004אשם \u0003מעילתו, ויביא עמה סלע וחומשה,\u0004 שהרי מעל בסלע, וצריך להוסיף עליו עוד חומש.","ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"מעילתו\" דקתני רישא\u0004 \u0005[שהוא שונה בתחילה]\u0006 כלומר, במקרה השני ששנינו, שאם קנה בכסף שהפריש לאשם שני אילים לחולין, אחד יפה שני סלעים ואחד יפה עשרה זוז, יקרב הראשון לאשמו \u0003והשני\u0004 השווה עשרה זוז \u0003למעילתו?\u0004","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ל\u0003איל אשם\u0004 מעילות, \u0003למימרא דחומש בהדי איל מייתי ליה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 מכאן \u0005שהחומש יחד עם איל\u0006 האשם \u0005מביא אותו],\u0006 שאם אשם המעילות שווה יותר משני סלעים יכול לצאת בעודף ידי חובת תשלום החומש על מה שגזל מן ההקדש? \u0003והכתיב\u0004 \u0005[והרי נאמר]: \"\u0006\u0003ואת אשר חטא מן הקדש ישלם ואת חמישתו יוסף עליו\"\u0004 (ויקרא ה, טז), \u0003אלמא בהדי גזילו מייתי ליה\u0004 \u0005[מכאן שיחד עם מה שגזל\u0006 מן ההקדש \u0005מביא אותו,\u0006 את החומש\u0005]!\u0006","\u0003ועוד, קתני סיפא\u0004 \u0005[הריהו שונה בסופה\u0006 של המשנה], בדין שאחריו: אם בשני הסלעים שהפריש לקח שני אילים, \u0003אחד לאשם ואחד לחולין, אם היה של אשם יפה שתי סלעים\u0004 — \u0003יקרב לאשמו\u0004 שהתחייב בו מתחילה, \u0003והשני\u0004 יקרב \u0003למעילתו, ויביא עמה סלע וחומשה, אלמא\u0004 \u0005[מכאן],\u0006 ממה שנאמר \"סלע וחומשה\", עולה בבירור שחומש \u0003בהדי גזילו מייתי ליה\u0004 \u0005[יחד עם גזילו מביא אותו]!\u0006","\u0003אלא\u0004 בהכרח, מה ששנינו בתחילה \"שהיפה עשרה זוז יהיה ל\u0003מעילתו\"\u0004 כוונתו — לתשלום \u0003מאי דאיתהני\u0004 \u0005[מה שנהנה]\u0006\u0003 מ\u0004ההקדש, ומפרטים: \u0003וישנו משתי סלעים דאפרישנו\u0004 \u0005[שהפריש אותם]\u0006 \u0003לאשם ולקח בהן שני אילים לחולין,\u0004 שה\u0003יפה שתי סלעים מקריב ליה\u0004 \u0005[אותו]\u0006 ל\u0003איל אשם, ו\u0004האיל \u0003יפה עשרה זוז יהיב ליה למאי דאיתהני\u0004 \u0005[נותן אותו למה שנהנה] מ\u0006ה\u0003הקדש,\u0004 שהשתמש בשני סלעים של הקדש, \u0003דהוה ליה\u0004 \u0005[ש\u0006עשרה זוז אלו \u0005הרי זה]\u0006 \u0003גזילו\u0004 (שני סלעים, שמונה זוז) \u0003וחומשו,\u0004 שני הזוזים היתרים. \u0003ומאי\u0004 \u0005[ו\u0006לפי זה \u0005מה\u0006 פירוש] \u0003\"מעילתו\"?\u0004 לא אשם המעילה, אלא \u0003גזילו,\u0004 כלומר תשלום מה שגזל מן ההקדש.","ומתקשים: \u0003במאי אוקימתא ל\" מעילתו\" דרישא\u0004 \u0005[במה העמדת,\u0006 הסברת \u0005את \"מעילתו\" שבתחילה]\u0006 — שהיא \u0003גזילו,\u0004 כלומר הסכום שעליו לשלם על מה שגזל מן ההקדש. ואולם \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של המשנה]: קנה בכסף הזה \u0003אחד לאשם ואחד לחולין, אם היה של אשם יפה שתי סלעים\u0004 — \u0003יקרב לאשמו\u0004 שהיה חייב בו מתחילה, \u0003והשני ל\u0004אשם \u0003מעילה, ויביא עמה סלע וחומשה;\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"מעילתו\"\u0004 כוונתו \u0003איל אשם\u0004 מעילות, שהרי אותו סלע וחומשה הוא גזילו. ותמוה הדבר, \u0003רישא קרי ליה\u0004 \u0005[בתחילה קורא לו,\u0006 משתמש בביטוי\u0005]\u0006 \u0003\"למעילתו\"\u0004 ביחס ל\u0003גזילו,\u0004 מה שצריך לשלם על שגזל מן ההקדש,"],["\u0003סיפא קרי ליה\u0004 \u0005[בסוף קורא לו]\u0006 \u0003\"למעילתו\" איל אשם!\u0004","ומשיבים: \u0003רישא\u0004 \u0005[בתחילה]\u0006 כשקנה בשני הסלעים אילים לחולין, \u0003דהוה ליה איל רובן\u0004 \u0005[שהאיל הגדול\u0006 שקנה בשווי עשרה זוז \u0005שווה]\u0006 ל\u0003קרן וחומשו\u0004 כלומר, לשני סלעים שמעל בהם ועוד חומש — \u0003קרו ליה\u0004 \u0005[קורא לו]\u0006 \u0003\"למעילתו\"\u0004 ל\u0003גזילו. סיפא\u0004 \u0005[בסוף]\u0006 שקנה בסלע אחד איל לחולין, \u0003דלא הוי איל רובן\u0004 \u0005[שהאיל הגדול\u0006 שקנה בעשרה זוז \u0005אינו שווה]\u0006 במדוייק ל\u0003קרן וחומש\u0004 — אין מקום לקרוא לו \"מעילתו\", ולכן \u0003קרי ליה\u0004 \u0005[קורא לו]\u0006 ל\u0003איל אשם \"מעילתו\", ויביא עמה סלע וחומשה.\u0004","ומביאים דיון שהובאה בו משנתנו כראיה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב מנשיא בר גדא\u0004 שאלה זו: \u0003בכינוס חומשין מהו שיתכפר?\u0004 אם מעל כמה פעמים בהקדש, עד שהחומשים עצמם הגיעו לשיעור של שני סלעים, האם יכול להביא בהם אשם ולהתכפר בכך?","ומפרטים את השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 גם \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 כי באופן עקרוני \u0003אדם מתכפר בשבח הקדש,\u0004 ברווח שהרויח מההקדש, וכגון שקנה איל אשם בשווי סלע, והגיע לשיעור שני סלעים — הרי זה \u0003משום דקטרח קמיה\u0004 \u0005[שהוא טורח בו],\u0006 שאיל זה נמצא ברשותו, והוא שומר עליו, \u0003אבל הכא דלא קטרח\u0004 \u0005[כאן שאינו טורח],\u0006 אלא שמצטבר אצלו כסף שהתחייב להקדש — \u0003לא מתכפר\u0004 בו.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר להיפך: גם \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ש\u0003אין אדם מתכפר בשבח הקדש,\u0004 כשהשביח האיל בידיו — הרי זה \u0003משום דלא אפרשיה\u0004 \u0005[שלא הפריש אותו]\u0006 כשהיה שווה שני סלעים, אלא מאליו בא השבח, \u0003אבל הדין\u0004 \u0005[זה]\u0006 \u0003כינוס חומשין דאפרשיה\u0004 \u0005[שהפריש אותו]\u0006 — \u0003איכא למימר\u0004 \u0005[יש לומר]\u0006 שהוא \u0003מתכפר\u0004 בו. \u0003דאיבעי להו\u0004 \u0005[שנשאלה להם,\u0006 לחכמים\u0005]\u0006 השאלה: האם \u0003מתכפר\u0004 אדם \u0003בשבח הקדש\u0004 שהשביח הקרבן ברשותו, \u0003או לא?\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה ממה ששנינו במשנתנו: \u0003המפריש שני סלעים לאשם, ולקח בהן שני אילים לאשם,\u0004 אם \u0003היה אחד מהן יפה שתי סלעים\u0004 — \u0003יקרב לאשמו, והשני ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה.\u0004","\u0003מאי לאו דזבן\u0004 \u0005[האם לא\u0006 מדובר \u0005שקנה]\u0006 \u0003בארבע\u0004 זוזים (שהם סלע) \u0003איל, ושבח\u0004 \u0005[והושבח]\u0006 האיל ברשותו, \u0003דשוי תמניא\u0004 \u0005[ש\u0006הוא \u0005שווה\u0006 עכשיו \u0005שמונה],\u0006 שהם שני סלעים, ולכן יכול להביא אותו כאשם? \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שאדם \u0003מתכפר בשבח הקדש!\u0004 ודוחים: \u0003לא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 באיל שהיה שווה שני סלעים כשקנה אותו, אלא \u0003דאוזיל רועה גביה\u0004 \u0005[שהרועה הוזיל\u0006 את המחיר \u0005בשבילו].\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה ממה ששנינו בברייתא: \u0003לקח\u0004 (קנה) \u0003איל בסלע, ופטמו והעמידו על שתים\u0004 (שני סלעים) — הרי זה \u0003כשר\u0004 לקרבן אשם. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאדם \u0003מתכפר בשבח\u0004 שהשביח \u0003הקדש!\u0004 ודוחים: \u0003לא,\u0004 אין מכאן ראיה, שכן מקרה ש\u0003פטמו שאני\u0004 \u0005[שונה],\u0006 \u0003דהא חסר ליה תמניא\u0004 \u0005[שהרי חסר לו שמונה\u0006 דינרים\u0005],\u0006 שבסך הכל הוציא שני סלעים על איל זה. אבל אם שבח מאליו ברשותו — אינו מתכפר בכך.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה ממה ששנינו בהמשך אותה ברייתא: \u0003לקח איל בסלע והרי הוא\u0004 עכשיו שווה \u0003בשתים\u0004 — \u0003כשר,\u0004 הרי שמתכפר אדם בשבח הקדש. ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כשפטמו.\u0004","ומקשים: \u0003אי הכי היינו רישא\u0004 \u0005[אם כך זהו\u0006 מה ששנינו ב\u0005תחילתה\u0006 של הברייתא\u0005],\u0006 ולא הוצרך לדין זה! ומשיבים: \u0003רישא דזבן\u0004 \u0005[בתחילה\u0006 מדובר \u0005שקנה]\u0006 איל \u0003בארבע\u0004 זוזים \u0003ואשבחיה\u0004 \u0005[והשביח אותו]\u0006 \u0003בארבעה\u0004 זוזים \u0003אחרינא\u0004 \u0005[אחרים]\u0006 שהוציא בפיטומו, \u0003דחסר ליה תמניא\u0004 \u0005[שחסר לו שמונה]\u0006 זוזים שהוציא על איל זה, שהם שני סלעים. ואילו \u0003סיפא דזבין\u0004 \u0005[בסוף\u0006 מדובר \u0005שקנה]\u0006 \u0003איל בארבע\u0004 זוזים \u0003ואשבחיה בתלתא\u0004 \u0005[והשביח אותו בשלושה]\u0006 זוזים שהוציא בפיטומו, ושבח מאליו בזוז נוסף, \u0003ושוי תמניא\u0004 \u0005[ו\u0006הוא \u0005שווה\u0006 עכשיו \u0005שמונה].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 ששנינו שם: ו\u0003ישלם סלע\u0004 משלו להקדש, ומדוע? \u0003הא חסר ליה\u0004 \u0005[הרי\u0006 כבר \u0005חסר לו]\u0006 באיל זה \u0003שבע\u0004 זוזים, שקנאו בארבעה זוזים ופיטמו בשלושה, ולא שבח האיל משל הקדש אלא זוז אחד! ומשיבים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003ישלם\u0004 סלע? כוונתו \u0003תשלום\u0004 של \u0003סלע,\u0004 מה שצריך להשלים לסלע, כלומר, זוז אחד.","ומקשים: \u0003ואי סבירא ליה\u0004 \u0005[אם סבור הוא]\u0006 שאין \u0003אדם מתכפר בשבח הקדש, כי יהיב\u0004 \u0005[כאשר יתן]\u0006 \u0003תשלום\u0004 של \u0003סלע,\u0004 כלומר זוז מביתו להקדש, \u0003מאי הוי\u0004 \u0005[מה בכך]?\u0006 הלוא \u0003איל בן שתי סלעים בעינן\u0004 \u0005[צריכים אנו],\u0006 שיחסר ממנו שני סלעים באיל זה שהוא מקריב, \u0003וליכא\u0004 \u0005[ואין כאן]!\u0006 אלא \u0003לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 תנא של ברייתא זו: \u0003אדם מתכפר בשבח הקדש.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003תשלום\u0004 של \u0003סלע לא יתן,\u0004 שהרי איל זה שווה עכשיו שני סלעים! ומשיבים: \u0003היינו טעמא דקיהיב\u0004 \u0005[זה הטעם שהוא נותן]\u0006 \u0003תשלומין\u0004 של הסלע — \u0003גזירה שמא יאמרו: איל פחות משתי סלעים מכפר.\u0004","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?\u0006 כיצד יש להכריע במחלוקת זו, האם מתכפר אדם בשבח הקדש או לא? ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו בברייתא: איל ש\u0003בשעת הפרשה\u0004 היה \u0003יפה סלע, בשעת כפרה\u0004 עלה ערכו והוא \u0003יפה שתי סלעים\u0004 — \u0003לא יצא,\u0004 ומכאן שאין אדם מתכפר בשבח הקדש.","ובענין זה עצמו מסופר, \u0003בעי\u0004 \u0005[שאל]\u0006\u0003 ר' אלעזר: אדם מתכפר בשבח הקדש או לא? אמר ר' יוחנן\u0004 בתמיהה: \u0003כמה שנים גדל זה בינינו,\u0004 ישב ר' אלעזר ולמד תורה מפי, \u0003ולא שמע הלכה זו ממני!\u0004","\u0003ושואלים: מכלל\u0004 הדברים אתה לומד שאמר ר' \u0003יוחנן\u0004 הלכה בענין זה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003ועל הדא אמרה\u0004 \u0005[ועל זו אמרה],\u0006 \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003ולד\u0004 קרבן \u0003תודה, ו\u0004כן \u0003תמורתה\u0004 בהמת חולין שהמיר בה קרבן תודה שלו, \u0003וכן המפריש\u0004 קרבן \u0003תודתו ואבדה והפריש אחרת תחתיה,\u0004 אף על פי שדינה של כל אחת מאלו ליקרב כתודה, \u0003אין טעונה לחם\u0004 שמביאים עם קרבן התודה.","\u0003ושלח ר' חנינא משמיה\u0004 \u0005[משמו]\u0006 של ר' \u0003יוחנן\u0004 בענין ולד התודה: \u0003לא שנו אלא לאחר כפרה\u0004 שהקריב את אמו וזרק את דמה, שאז ה\u0003ולד אין טעון לחם,\u0004 מפני שאינו יוצא בו ידי חובתו.","\u0003אבל\u0004 אם הקריבו \u0003לפני כפרה\u0004 כלומר, לפני שהקריב את אמו — \u0003טעון\u0004 הולד \u0003לחם,\u0004 ויוצא בו ידי חובת תודתו במקום אמו, \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 שאדם \u0003מתכפר בשבח הקדש,\u0004 שהרי ולד זה נולד לבהמת הקדש, ובעליו מתכפר בו.","אגב כך מביאים מעשה דומה, \u0003בעי\u0004 \u0005[שאל]\u0006\u0003 ר' אלעזר: בעלי חיים נדחין או לא\u0004 כלומר, קרבן שנדחה מהקרבה מסיבה כל שהיא, האם דחייתו היא מוחלטת והוא פסול לעולם, או שמא הוא חוזר להכשרו? \u0003אמר ר' יוחנן\u0004 בפליאה: \u0003הרי כמה שנים גדל זה בינינו, ולא שמע הלכה זו ממני!\u0004","ושואלים: האם \u0003מכלל\u0004 הדברים אתה לומד שר' \u0003יוחנן אמרה\u0004 \u0005[אמר אותה]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 ש\u0003אמר ר' יוחנן: בהמה של שני שותפין, הקדיש\u0004 אחד מהם את \u0003חציה, וחזר ולקח\u0004 (וקנה) מחבירו את \u0003חציה\u0004 השני, \u0003והקדישה\u0004 גם את החצי שקנה — \u0003קדושה\u0004 הבהמה, אבל \u0003אינה קריבה, ו\u0004היא \u0003עושה תמורה,\u0004 שאם המיר אותה בבהמת חולין — גם בהמת החולין מתקדשת בקדושתה, \u0003ו\u0004דין \u0003תמורתה כיוצא בה,\u0004 שאינה קריבה.","\u0003שמע מינה תלת\u0004 \u0005[למד ממנה\u0006 מהלכה זו של ר' יוחנן שלושה דברים]: \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שבעלי \u0003חיים\u0004 שנדחו מהקרבה \u0003נדחין\u0004 לעולם, ולכן כשהקדיש חציה מתחילה, הואיל ולא היתה ראויה אז להקרבה, אינה קריבה גם כאשר חוזר ומקדיש את החלק השני. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שקדושת \u0003דמים מדחה\u0004 עושה בהמה אחרת דחויה כמותה, כלומר, את תמורתה, שהרי הקדושה הראשונה שהקדישה לא היתה קדושת הגוף, שהרי אינו יכול להקריב מחצית בהמה. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שיש \u0003דיחוי בדמים,\u0004 שגם דבר שהוקדש רק לדמיו נדחה מהקרבה.","עוד בענין אשם בשני סלעים, \u0003בעי\u0004 \u0005[שאל] ר'\u0006 \u0003אלעזר:\u0004 אם ה\u0003וזלו טלאים בעולם\u0004 בכלל, ואין איל ששווה שני סלעים, \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003\"מבחר נדריכם\"\u0004 (דברים יב, יא) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא איכא\u0004 \u0005[והרי יש כאן],\u0006 שהוא מביא את המובחר שיש, \u0003או דילמא\u0004 \u0005[שמא]\u0006 אשם ב\u0003\"כסף שקלים\"\u0004 (ויקרא ה, טו) \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003וליכא\u0004 \u0005[ואין כאן]?\u0006","\u0003אמר ר' יוחנן: כמה שנים גדלנו בבית המדרש ולא שמענו הלכה זו.\u0004 ושואלים: \u0003ולא,\u0004 האם לא שמע? \u0003והאמר\u0004 \u0005[והרי אמר] ר'\u0006 \u0003יוחנן אמר ר' שמעון בן יוחאי: מפני מה לא נתנה תורה קצבה\u0004 שווי לקרבנות \u0003במחוסרי כפרה\u0004 כגון זב ומצורע, שצריכים קרבן לטהרם לאכילת קדשים? \u0003שמא יוזלו טלאים\u0004 מן הקצבה שנתנה התורה, \u0003ו\u0004אז \u0003אין להן תקנה לאכול בקדשים.\u0004 משמע במפורש מדבריו שאיל אשם, שקצבה לו התורה שני סלעים, אינו קרב בפחות מכך! ומשיבים, \u0003אימא\u0004 \u0005[אמור]\u0006 כך אמר ר' יוחנן: כמה שנים \u0003לא לימדנו הלכה זו\u0004 בבית המדרש.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006\u0003 ר' זירא בר אדא מהדר תלמודיה כל תלתין יומין קמיה\u0004 \u0005[היה חוזר על תלמודו כל שלושים יום לפניו],\u0006 לפני ר' יוחנן, ונמצא שדבריו של ר' יוחנן חזרו ונאמרו! ומשיבים, \u0003אימא\u0004 \u0005[אמור]\u0006 שכך אמר ר' יוחנן: \u0003לא נתבקשה הלכה זו ממנו בבית המדרש,\u0004 לא נשאלנו עליה.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר ר' יוחנן משום ר' שמעון בן יוחאי: מפני מה לא נתנה קצבה במחוסרי כפרה? שמא יוזלו טלאים, ואין להם תקנה לאכול בקדשים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: אלא מעתה, חטאת חלב\u0004 כלומר, חטאת שמביא על חטא \u0003ינתן לה קצבה, דלכפרה אתיא\u0004 \u0005[ש\u0006הרי \u0005לכפרה היא באה]\u0006 \u0003ולאו לאישתרויי\u0004 \u0005[ולא להתיר]\u0006 \u0003באכילת קדשים הוא!\u0004 וכן, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: אלא מעתה, אשם נזיר\u0004 טמא \u0003להוי ליה\u0004 \u0005[שתהיה לו]\u0006 \u0003קצבה\u0004 בתורה, \u0003דלבטלה הוא דאתי\u0004 \u0005[שלחינם הוא שבא],\u0006 שאינו בא להכשירו לאכילת קדשים, ודי לו שייטהר מטומאתו לשם כך, שאמר ר' \u0003יוחנן משום ר' שמעון בן יוחאי: אין לך דבר שהוא בא לבטלה,\u0004 שאין לו תיקון מוגדר ומסויים לעצמו, \u0003אלא אשם נזיר בלבד!\u0004 ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 ענין זה."],["\u0003המפריש חטאתו\u0004 על שגגתו \u0003ומת\u0004 — \u0003לא יביאנו בנו תחתיו\u0004 לא על חיוב של אביו ולא על שגגת עצמו, אפילו היה זה אותו חטא. וכן המפריש חטאתו \u0003לא יביאנו\u0004 הוא עצמו \u0003מחטא אל חטא\u0004 כלומר, על חטא אחר. ויותר מכך, \u0003אפילו הפריש על\u0004 שגגת \u0003חלב שאכל אמש\u0004 — \u0003לא יביאנה\u0004 את החטאת הזו \u0003על חלב שאכל היום, שנאמר:\u0004 \"והביא \u0003קרבנו על חטאתו\"\u0004 (ויקרא ד, כח) — \u0003עד שיהא קרבנו לשם חטאתו\u0004 שעבורה הפריש.","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בקרבן חטאת \"והביא את \u0003קרבנו\"\u0004 (ויקרא ד, כג), להדגיש — \u0003בקרבנו הוא יוצא, ואינו יוצא בקרבן\u0004 שהפריש \u0003אביו\u0004 לחטאתו, ומת.","ודנים בדבר: \u0003יכול לא יצא בקרבן אביו בבהמה שהפריש אביו\u0004 דווקא בסוג שונה של עבירות, \u0003מן הקלה\u0004 שלשמה הפריש אביו חטאתו \u0003על החמורה\u0004 יותר שעבר הוא, \u0003או מן החמורה\u0004 שלשמה הפריש אביו חטאתו \u0003על הקלה\u0004 שעבר הוא, \u0003אבל יוצא בקרבן שהפריש אביו מן הקלה על הקלה או מן החמורה על החמורה,\u0004 ששתיהן באותה חומרה? על כן \u0003תלמוד לומר\u0004 שוב: \u0003\"קרבנו\"\u0004 (שם כח) להשמיענו — \u0003בקרבנו הוא יוצא, ואינו יוצא בקרבנו של אביו.\u0004","ועוד, \u0003יכול לא יצא בקרבן\u0004 של \u0003אביו\u0004 דווקא \u0003בבהמה שהפריש\u0004 אביו, \u0003אפילו מן הקלה על הקלה או מן החמורה על החמורה, שהרי\u0004 אף \u0003אין מגלח נזירותו על בהמה שהפריש אביו\u0004 ומת, שאינו יכול להביא בסוף נזירותו קרבנות שהפריש אביו לשם כך,","\u0003אבל\u0004 שמא \u0003יוצא במעות שהפריש אביו\u0004 לשם חטאתו, \u0003אפילו מן הקלה על החמורה או מן החמורה על הקלה, שהרי אדם מגלח נזירותיו על מעות שהפריש אביו\u0004 לצורך זה, \u0003בזמן שהן סתומים\u0004 כשלא פירש לאיזה קרבן מקרבנות הנזירות מיועד כל חלק מן המעות, \u0003ולא בזמן שהן מפורשין? תלמוד לומר\u0004 שוב: \u0003\"קרבנו\"\u0004 (שם לב), להשמיענו: \u0003בקרבנו הוא יוצא, ואין יוצא בקרבן אביו,\u0004 ואפילו במעות שהפריש אביו.","\u0003יכול לא יצא אפילו במעות שהפריש\u0004 אביו \u0003אפילו מן הקלה על הקלה או מן החמורה על החמורה, אבל יוצא בקרבן שהפריש\u0004 הוא \u0003לעצמו, אפילו מן החמורה על הקלה או מן הקלה על החמורה? תלמוד לומר: \"קרבנו על חטאתו\",\u0004 ומן המלה \"חטאתו\" יש לדייק — \u0003עד שיהא לשם חטאת\u0004 זו שחטא בה.","\u0003יכול לא יצא בקרבן\u0004 של \u0003עצמו בבהמה שהפריש לעצמו, אפילו מן הקלה על הקלה או מן החמורה על החמורה, שכן אם הפריש בהמה על\u0004 אכילת \u0003החלב\u0004 בשגגה \u0003והביאה על\u0004 אכילת \u0003הדם,\u0004 או הפריש \u0003על הדם והביאה על החלב\u0004 — \u0003שהרי\u0004 במקרה זה \u0003לא מעל\u0004 בהקדש \u0003ו\u0004לכן \u0003לא כיפר,\u0004","\u0003אבל יוצא\u0004 הוא \u0003במעות שהפריש לעצמו מן הקלה על הקלה ומן החמורה על החמורה, או מן החמורה על הקלה ומן הקלה על החמורה,\u0004","\u0003שכן אם הפריש לעצמו מעות על החלב והביאן על הדם, על הדם והביאן על החלב\u0004 — \u0003שהרי מעל\u0004 בהקדש, \u0003ו\u0004לכן \u0003כיפר? תלמוד לומר: \"קרבנו על חטאתו\"\u0004 — \u0003עד שיהא קרבנו לשם חטאו,\u0004 ואפילו המעות.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש] \"שהרי \u0003לא מעל ולא כיפר\"? תרגמא\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 \u0003רב שמואל בר שימי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 בבהמה, \u0003כיון דלא מצי מעיל\u0004 \u0005[שאינו יכול למעול]\u0006 בה, שאינו יכול להוציא אותה לחולין על ידי כך, לכן \u0003כפורי נמי לא מכפר\u0004 \u0005[לכפר\u0006 על חטא אחר \u0005גם כן אינו מכפר],\u0006 \u0003הואיל וכך\u0004 מובן מדוע \u0003לא מצי משני\u0004 \u0005[אינו יכול,\u0006 רשאי \u0005לשנות]\u0006 אותה לשם חטא אחר.","\u0003אבל מעות, כיון דאי משני\u0004 \u0005[שאם משנה]\u0006 אותם בשוגג \u0003מעיל\u0004 \u0005[מועל\u0006 בכך\u0005]\u0006 \u0003ומייתי\u0004 \u0005[ומביא]\u0006 \u0003קרבן מעילה,\u0004 ואם כן יש בכוחו לשנות את ייעודם — \u0003אימא בתחלה נמי מייתי\u0004 \u0005[אמור שלכתחילה גם כן מביא]\u0006 בהם קרבן לחטא אחר, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינו רשאי לעשות כן.","\u0003מביאין מהקדש כשבה שעירה\u0004 אם הפריש כסף לקנות בו כשבה לחטאתו, יכול לשנות ולקנות בו שעירה לשם אותו חטא, וכן מביאים \u0003מהקדש שעירה\u0004 — \u0003כשבה. ו\u0004כן \u0003מהקדש כשבה ושעירה\u0004 יכול להביא \u0003תורין ובני יונה, ומהקדש תורין ובני יונה\u0004 יכול להביא קרבן מנחה של \u0003עשירית האיפה\u0004 סולת.","\u0003כיצד?\u0004 אדם שחטא באחד מן החטאים שמביא עליהם קרבן \"עולה ויורד\", שמשתנה לפי מצבו הכלכלי (ראה ויקרא ה, א—יג), אם \u0003הפריש\u0004 מעות \u0003לכשבה או לשעירה\u0004 ואחר כך \u0003העני,\u0004 ואין ידו משגת לקרבן מן הצאן — \u0003יביא עוף\u0004 במעות אלו, \u0003העני\u0004 עוד יותר — \u0003יביא עשירית האיפה.\u0004 וכן להיפך, אם \u0003הפריש\u0004 מעות \u0003לעשירית האיפה\u0004 ואחר כך \u0003העשיר\u0004 — \u0003יביא עוף, העשיר\u0004 יותר — \u0003יביא כשבה ושעירה.\u0004","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בענין קרבן עולה ויורד: מה שנאמר בקרבן מן הצאן \"וכפר עליו הכהן \u0003מחטאתו\"\u0004 (ויקרא ה, ו), ובקרבן מן העוף \"וכפר עליו הכהן \u0003מחטאתו\"\u0004 (שם י), ובעשירית האיפה \u0003\"על חטאתו\"\u0004 (שם יג), \u0003מה תלמוד לומר?\u0004","ומשיבים: \u0003מנין אתה אומר שמביאין מהקדש כשבה\u0004 — \u0003שעירה, ומהקדש שעירה\u0004 — \u0003כשבה, ומהקדש כשבה ושעירה\u0004 — \u0003תורים ובני יונה, ומהקדש תורין ובני יונה\u0004 — \u0003עשירית האיפה,\u0004","\u0003כיצד?\u0004 אם \u0003הפריש\u0004 מעות \u0003לכשבה ולשעירה והעני\u0004 — \u0003יביא עוף, העני\u0004 יותר — \u0003יביא עשירית האיפה,\u0004 וכן אם \u0003הפריש עשירית האיפה והעשיר\u0004 — \u0003יביא עוף, העשיר\u0004 יותר — \u0003יביא כשבה או שעירה.\u0004","וכן אם \u0003הפריש כשבה או שעירה ונסתאבו\u0004 (ונפל בהם מום), וצריך לפדותם ולהביא בדמיהם קרבן אחר, והעני — \u0003יביא בדמיהן עוף,\u0004 אבל אם \u0003הפריש עוף ונסתאב\u0004 — \u0003לא יביא בדמיו עשירית האיפה, שאין לעוף פדיון.\u0004","ושבים לעיקר הענין, \u0003לכן נאמר\u0004 בקרבן מן הצאן ובקרבן מן העוף \u0003\"מחטאתו\",\u0004 במ', לומר: יוצא אפילו במקצת דמי חטאתו, ובעשירית האיפה נאמר \"על חטאתו\" ללמד שאם העשיר מוסיף על דמי חטאתו.","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב] \"\u0006\u0003מחטאתו\" גבי\u0004 \u0005[אצל]\u0006 \u0003כשבה או שעירה, ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 גם \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עוף. דאי כתיב קרא\u0004 \u0005[שאם היה נאמר המקרא]\u0006 לגבי \u0003הקדש כשבה או שעירה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כך: אם \u0003הפריש\u0004 מעות ל\u0003כשבה, כי מיעני\u0004 \u0005[כאשר הוא נעשה עני]\u0006 \u0003מהלין מעות נחלינון\u0004 \u0005[מאותן מעות יחלל אותם]\u0006 \u0003על עוף, דנייתי\u0004 \u0005[שיביא]\u0006 \u0003עוף\u0004 במקום הכשבה, שכן \u0003כשבה ועוף תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003מיני\u0004 קרבנות של \u0003דמים נינהו\u0004 \u0005[הם].\u0006","\u0003אבל עשירית האיפה דלאו מיני דדמים נינהו\u0004 \u0005[שלא מין של דמים הם],\u0006 אלא מנחה, \u0003אי לא כתיב קרא\u0004 \u0005[אם לא היה נאמר המקרא] \"\u0006\u0003מחטאתו\" גבי\u0004 \u0005[אצל]\u0006 \u0003עוף,\u0004 שיכול להשתמש במקצת הדמים, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מפריש מעות לקינו ומיעני\u0004 \u0005[ונעשה עני]\u0006 — \u0003לא מייתי\u0004 \u0005[מביא]\u0006 \u0003עשירית האיפה, דלאו\u0004 \u0005[שאין זה]\u0006 \u0003מיני\u0004 \u0005[ממין]\u0006 של \u0003דמים הוא, אלא מייתי\u0004 \u0005[מביא]\u0006 \u0003עשירית האיפה מן ביתיה\u0004 \u0005[מביתו],\u0006 \u0003והלין\u0004 \u0005[ואותם]\u0006 \u0003מעות דאפריש\u0004 \u0005[שהפריש]\u0006 \u0003יפלו לנדבה,\u0004 להקריב מהם קרבנות ציבור — \u0003אהכי הדר כתיב קרא\u0004 \u0005[משום כך חזר\u0006 ו\u0005נכתב המקרא] \"\u0006\u0003מחטאתו\" גבי\u0004 \u0005[אצל]\u0006 \u0003עוף, למימרא\u0004 \u0005[לומר]\u0006 שמהקדש של \u0003עוף נמי מייתי\u0004 \u0005[גם כן מביא]\u0006 \u0003עשירית האיפה,\u0004","\u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מפריש\u0004 מעות \u0003לעשירית האיפה, ואדמייתי\u0004 \u0005[ועד שהוא מביא]\u0006 אותם למקדש כדי לקנות בהם קרבן \u0003העשיר\u0004 — \u0003נוסיף עליהון ונייתי\u0004 \u0005[יוסיף עליהם\u0006 מעות \u0005ויביא]\u0006 \u0003עוף, העשיר\u0004 עוד — \u0003נוסיף עליהון ונייתי\u0004 \u0005[יוסיף עליהם ויביא]\u0006 \u0003כשבה או שעירה.\u0004","ומוסיפים: \u0003ומאי טעמא כתיב\u0004 \u0005[ומה טעם נאמר] \"\u0006\u0003על חטאתו\" גבי\u0004 \u0005[אצל]\u0006 \u0003עשירית האיפה? דאי כתיב\u0004 \u0005[שאילו היה נאמר] \"\u0006\u0003על חטאתו\" גבי\u0004 \u0005[אצל]\u0006 \u0003עוף, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מפריש מעות לקינו והעשיר\u0004 — \u0003הוא דמוסיף עליהון ומייתי\u0004 \u0005[שמוסיף עליהם ומביא]\u0006 \u0003כשבה או שעירה,\u0004 מפני \u0003דתרוייהו\u0004 \u0005[ששניהם]\u0006 \u0003מיני דמים נינהו\u0004 \u0005[הם],\u0006","\u0003אבל\u0004 אם \u0003הפריש מעות לעשירית האיפה והעשיר, הלין\u0004 \u0005[אותם]\u0006 שמפריש עכשיו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא העשיר טובא\u0004 \u0005[הרבה],\u0006 אלא מעט — \u0003נייתי\u0004 \u0005[שיביא]\u0006 בהם \u0003עוף, ואם העשיר טובא\u0004 \u0005[הרבה]\u0006 — \u0003נייתי\u0004 \u0005[שיביא]\u0006 \u0003כשבה או שעירה, והלין מעות דאפריש\u0004 \u0005[ואותם המעות שהפריש]\u0006 מתחילה לעשירית האיפה \u0003יפלו לנדבה, אהכי כתיב קרא בהדין\u0004 \u0005[משום כך נכתב במקרא באותה]\u0006 \u0003חטאת\u0004 שמביא \u0003בעשירות ודלות\u0004 (בצאן ובעוף) \u0003\"מחטאתו\", וגבי\u0004 \u0005[ואצל]\u0006 \u0003דלי דלות\u0004 (עשירית האיפה) \u0003\"על חטאתו\"\u0004 — \u0003למדרש כדאמרינן\u0004 \u0005[לדרוש\u0006 את המקראות \u0005כמו שאמרנו].\u0006","\u0003אמר ר' אלעזר אמר ר' אושעיא: מטמא מקדש עשיר שהפריש קן\u0004 עופות"],["\u0003לכבשתו\u0004 כלומר, במקום כבשתו, שאף שהיה עשיר רצה להביא קרבן עני, ואינו רשאי לעשות כן, ולבסוף \u0003העני.\u0004 למרות שעכשיו ראוי לו קרבן זה, מכל מקום \u0003הואיל ונדחה\u0004 בשעתו, שלא היה ראוי להביא אותו — \u0003ידחה\u0004 לעולם.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, שמע מינה תלת\u0004 \u0005[למד ממנה\u0006 מהלכה זו \u0005שלושה\u0006 דברים\u0005]\u0006\u0003: שמע מינה\u0004 \u0005[למד ממנה]\u0006 שבעלי \u0003חיים נדחים\u0004 לגמרי מהקרבה, למרות שאין פסול בגופם, וכגון קן זה. \u0003ו\u0004למד מכאן שמה שנתקדש ב\u0003קדושת דמים\u0004 גם כן \u0003נדחה,\u0004 שהרי כשהיה עשיר והפריש קן זה — לא היה ראוי להקרבה, ולא נתקדש אלא לדמיו, ומכל מקום נדחה.","\u0003ו\u0004עוד למד מכאן שדבר שהוא \u0003דחוי מעיקרא\u0004 \u0005[מתחילתו]\u0006 \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003דחוי,\u0004 כגון קן זה שמתחילתו לא היה ראוי להקרבה, ולא רק מה שהיה ראוי מתחילתו ואחר כך נדחה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב עוקבא בר חמא\u0004 ממה ששנינו: \u0003המפריש נקבה לפסחו קודם הפסח,\u0004 ואין קרבן פסח אלא מן הזכרים — \u0003תרעה\u0004 בהמה זו \u0003עד שתסתאב\u0004 (שיפול בה מום), \u0003ותמכר ויביא בדמיה\u0004 קרבן \u0003פסח.\u0004 וכן אם \u0003ילדה\u0004 בהמה זו \u0003זכר\u0004 — \u0003ירעה\u0004 הזכר \u0003עד שיסתאב וימכר ויביא בדמיו פסח.\u0004","\u0003ר' שמעון אומר:\u0004 במקרה זה אינו צריך למוכרו, אלא \u0003הוא עצמו,\u0004 הוולד, \u0003יקרב פסח. שמע מינה\u0004 \u0005[למד מכאן]\u0006 מדברי ר' שמעון, שבעלי \u0003חיים אינם נדחים,\u0004 שהרי הנקבה שהפריש לא היתה ראויה לפסח, וולדה הבא מכוחה קרב!","\u0003אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של ר' \u0003אושעיא: כי אמרינן\u0004 \u0005[כאשר אמרנו]\u0006 שבעלי חיים נדחים הרי זה \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים],\u0006 הסבורים כי ולד זה אינו קרב, ואילו ר' \u0003שמעון סבירא ליה\u0004 \u0005[סבור]\u0006 ש\u0003בעלי חיים אינן נדחין, ו\u0004כן הוא סבור שהגרלה של שני שעירי יום הכיפורים","\u0003אינה מעכבת. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 הביאו שני שעירים והגריל עליהם הכהן הגדול, ואמר על אחד \"לה'\" ועל אחד \"לעזאזל\", ו\u0003מת אחד מהן,\u0004 כגון השעיר לעזאזל — \u0003מביא\u0004 במקומו \u0003חבירו,\u0004 שעיר אחר, \u0003שלא בהגרלה,\u0004 והשעיר לה' יקרב, אלו \u0003דברי ר' שמעון.\u0004","\u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 שבעלי \u0003חיים אינן נידחין,\u0004 שהשעיר לה', למרות שנדחה מהקרבה עד שהביא שעיר אחר — כשר להקרבה, \u0003והגרלה אינה מעכבת,\u0004 שהרי בשעיר החדש לעזאזל לא היתה הגרלה, ונקבע רק בהקצאתו לצורך זה.","\u0003אמר רב חסדא: אין הקינין,\u0004 זוג ציפורים שמביאים לקרבנות העוף, אחד חטאת ואחד עולה, \u0003מתפרשות\u0004 נקבעות איזו לחטאת ואיזו לעולה, \u0003אלא אי\u0004 \u0005[או]\u0006 \u0003בלקיחת בעלים\u0004 כאשר הבעלים קונים אותן ומפרשים מה לחטאת ומה לעולה, \u0003אי\u0004 \u0005[או]\u0006 אם לא פירשו הבעלים — \u0003בעשיית כהן,\u0004 כאשר הוא מקריב אותן.","\u0003אמר רב שימי בר אשי: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רב חסדא? דכתיב\u0004 \u0005[שנאמר]\u0006 בקרבן יולדת: \u0003\"ולקחה שתי תרים\u0004 או שני בני יונה אחד לעולה ואחד לחטאת\" (ויקרא יב, ח), ובקרבן מצורע נאמר: \u0003\"ועשה הכהן\u0004 את האחד חטאת ואת האחד עולה\" (שם טו, ל), לומר כי החטאת והעולה נקבעות \u0003אי בלקיחת בעלים אי בעשיית כהן.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא לגבי שעירי יום הכיפורים: נאמר \"והקריב אהרן את השעיר אשר עלה עליו הגורל לה' \u0003ועשהו חטאת\"\u0004 (שם טז, ט) — \u0003הגורל עושהו חטאת,\u0004 עצם עליית הגורל לשמו מתוך הקלפי — \u0003ואין\u0004 קריאת \u0003השם עושהו חטאת, ואין כהן\u0004 בעשייתו (שמניח עליו את הגורל לה') \u0003עושה חטאת.\u0004","והוצרך הכתוב להדגיש דבר זה, \u0003שיכול\u0004 היית לומר: \u0003והלא דין\u0004 קל וחומר \u0003הוא, ומה במקום שלא קידש הגורל\u0004 בשאר קרבנות, שאין מקדישים אותם על ידי גורל — \u0003קידש השם,\u0004 כאשר אדם אומר \"הרי זה חטאת\", \u0003מקום שיקדש הגורל\u0004 בשעיר של יום הכיפורים — \u0003אינו דין שיקדש השם?\u0004","\u0003תלמוד לומר:\u0004 \"אשר עלה עליו הגורל לה' \u0003ועשהו חטאת\",\u0004 לומר: \u0003הגורל עושהו חטאת, ואין השם עושהו חטאת.\u0004","והרי \u0003קתני\u0004 \u0005[הוא שונה]\u0006 בברייתא זו קידוש על ידי קריאת \u0003שם דומיא\u0004 \u0005[בדומה]\u0006 לגורל, ומשם נלמד: \u0003מה גורל לאו\u0004 \u0005[אינו]\u0006\u0003 ב\u0004זמן \u0003לקיחה ולאו\u0004 \u0005[ולא] ב\u0006זמן \u0003עשייה, אף השם\u0004 שקובעים עליו \u0003נמי\u0004 \u0005[גם כן]\u0006 אינו נקבע \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ב\u0004שעת \u0003לקיחה ולאו\u0004 \u0005[ולא]\u0006 \u0003ב\u0004שעת \u0003עשייה\u0004 של הכהן, אלא אפילו באמצע, שלא כדברי רב חסדא!","\u0003אמר רב, הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 התנא: \u0003ומה במקום שלא קידש הגורל,\u0004 והוא \u0003בלקיחת בעלים ובעשיית הכהן\u0004 — \u0003קידש השם, אי\u0004 \u0005[או]\u0006 \u0003בלקיחת בעלים אי\u0004 \u0005[או]\u0006 \u0003בעשיית כהן, כאן\u0004 בשעיר יום הכיפורים \u0003שיקדש הגורל שלא בלקיחה ושלא בעשייה\u0004 — \u0003אינו דין שיקדש השם אי\u0004 \u0005[או]\u0006 \u0003בלקיחה אי\u0004 \u0005[או]\u0006 \u0003בעשייה?\u0004","\u0003תלמוד לומר: \"ועשהו חטאת\",\u0004 לומר שהגורל \u0003עושהו חטאת, ואין\u0004 קריאת \u0003השם עושהו חטאת.\u0004","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 לרב חסדא ממה ששנינו: \u0003מטמא מקדש עני\u0004 שנכנס טמא למקדש בשוגג, ודינו בקרבן עולה ויורד, \u0003שהפריש מעות לקינו\u0004 (לקרבן מן העוף), שיש בו שני עופות, אחד לחטאת ואחד לעולה, \u0003והעשיר,\u0004 והוא צריך להוסיף מעות ולהביא כבשה או שעירה לחטאת.","אם \u0003אמר\u0004 \"מעות \u0003אלו לחטאתי ו\u0004מעות \u0003אלו לעולתי\",\u0004 וטעה, שהרי אין בקרבנו עולה — \u0003מוסיף\u0004 מעות \u0003ומביא\u0004 את \u0003חובתו מדמי חטאתו\u0004 (מן המעות שאמר עליהן \"אלו לחטאת\"), \u0003ואין מוסיף ומביא\u0004 חובתו \u0003מדמי עולתו,\u0004 שאינו יכול לשנות את מעות העולה לחטאת.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 בשעה שאמר \"אלו לחטאתי ואלו לעולתי\" \u0003דליכא\u0004 \u0005[שאין\u0006 זה\u0005]\u0006 \u0003לא\u0004 שעת \u0003לקיחה,\u0004 שהרי כבר הפריש את המעות, \u0003ולא\u0004 שעת \u0003עשייה\u0004 על ידי הכהן, \u0003וקתני\u0004 \u0005[והוא שונה]:\u0006 \u0003מביא חובתו מדמי חטאתו, ולא מדמי עולתו,\u0004 ומכאן שנקבעו המעות לכך בשעה שאמר כן!","\u0003אמר רב ששת: ותסברא מתניתא מתקנתא\u0004 \u0005[וכי סבור אתה שברייתא זו מתוקנת]\u0006 \u0005היא, במה\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 בה: \u0003והעשיר\u0004 ואחר כך אמר \"אלו לחטאתי ואלו לעולתי\"? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006\u0003 ר' אלעזר אמר ר' אושעיא: מטמא מקדש עשיר שהביא קרבן עני\u0004 — \u0003לא יצא\u0004 כלל, ואיך היה יכול לקבוע מה חטאת ומה עולה בקרבן שאינו יכול להקריבו!","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]?\u0006 שמדובר \u0003שכבר אמר\u0004 \"אלו לחטאתי ואלו לעולתי\" \u0003משעת ענייתו,\u0004 בשעה שהיה עני, ולא לאחר שהעשיר, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אפשר לומר \u0003שכבר אמר\u0004 כן \u0003משעת הפרשתו,\u0004 כשהפריש את המעות, ואין מכאן קושיה לרב חסדא.","ושואלים: ולדעת ר' \u0003חגא\u0004 ש\u0003אמר\u0004 בשם ר' \u0003אושעיא\u0004 שאמר: עשיר שהביא קרבן עני \u0003יצא,\u0004 וברייתא זו מתוקנת היא כפשוטה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע אינו יכול לשנות את דמי העולה? הרי אמר \"אלו לחטאתי ואלו לעולתי\" שלא בשעת לקיחה! ומשיבים, לשיטתו \u0003תני\u0004 \u0005[שנה]\u0006 כך: \u0003ואחר כך,\u0004 לאחר שהעשיר \u0003לקח ואמר\u0004 באותה שעה \"אלו לחטאתי ואלו לעולתי\".","ולגופה של מחלוקת ר' אלעזר ור' חגא בשם ר' אושעיא, האם עשיר שהביא קרבן עני יצא, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בענין מצורע, שגם בו יש דין עשירות ועניות: \u0003מצורע עני שהביא קרבן עשיר\u0004 — \u0003יצא\u0004 בו ידי חובה, מצורע \u0003עשיר שהביא קרבן עני\u0004 — \u0003לא יצא,\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על ר' \u0003חגא אמר ר' אושעיא!\u0004","ומשיבים, \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך\u0004 ר' חגא: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003הדין לגבי\u0004 \u0005[אצל]\u0006 \u0003מצורע\u0004 עשיר, \u0003דמיעט רחמנא\u0004 \u0005[שמיעט הכתוב]\u0006\u0003 \"זאת\u0004 תהיה תורת המצורע\" (ויקרא יד, ב), לומר — כך ולא באופן אחר, ואם היה עשיר אינו יוצא בקרבן עני.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 משום גזירת הכתוב, \u0003אפילו מצורע עני נמי\u0004 \u0005[גם כן]\u0006 \u0003שהביא קרבן עשיר\u0004 — \u0003לא יצא!\u0004 ודוחים: \u0003לאיי\u0004 \u0005[אינו כן],\u0006 \u0003הא אהדריה קרא\u0004 \u0005[הרי החזירו הכתוב]\u0006 ואמר \u0003\"תורת\u0004 המצורע\", שהיא לשון ריבוי. ומעירים, \u0003והתניא\u0004 \u0005[וכן שנויה\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"תורת\u0004 המצורע\" — בא \u0003לרבות מצורע עני שהביא קרבן עשיר\u0004 שיצא. \u0003יכול אפילו עשיר שהביא קרבן עני שיצא? תלמוד לומר: \"זאת\".\u0004","ושואלים: \u0003ולילף מיניה\u0004 \u0005[ושנלמד מכאן]\u0006 הלכה כללית לשאר חייבי קרבן עולה ויורד, שכל עשיר שהביא קרבן עני לא יצא! ומשיבים, \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לגבי מצורע: \u0003\"ואם דל הוא ואין ידו משגת\"\u0004 (שם כא), והמלה \"הוא\" באה להדגיש: \u0003מצורע הוא\u0004 דינו כן, שעשיר \u0003שהביא קרבן עני הוא\u0004 שלא \u0003יצא, אבל מטמא מקדש עשיר שהביא קרבן עני\u0004 — \u0003יצא\u0004 בכל זאת.","בענין ששנינו במשנה הקודמת, שמביאים מהקדש כשבה שעירה ולהיפך, מביאים מה שר' שמעון אומר: כבשים \u0003קודמין את העזים בכל מקום,\u0004 שבכל מקום בתורה נאמרו כבשים לפני עיזים, וכגון \"מן הכבשים ומן העזים תקחו\" (שמות יב, ה), \u0003יכול מפני שהן מובחרים מהם,\u0004 שאם יש אפשרות מוטב להביא כבש? \u0003תלמוד לומר\u0004 בענין קרבן החטאת: \"והביא קרבנו שעיר עזים\", (ויקרא ד, כח), ואחר כך: \u0003\"ואם כבש יביא קרבנו לחטאת\"\u0004 (שם לב) — \u0003מלמד ששניהם שקולין.\u0004","וכן \u0003תורין קודמין לבני יונה בכל מקום\u0004 בתורה (ראה ויקרא ה, ז ועוד), \u0003יכול מפני שהן מובחרים מהן? תלמוד לומר\u0004 בקרבן היולדת: \"(תור ובני) [ובן] \u0003יונה או תור לחטאת\"\u0004 (שם יב, ו), בן יונה ואחר כך תור — \u0003מלמד ששניהם שקולין.\u0004","וכן \u0003האב קודם לאם בכל מקום\u0004 בתורה, וכגון \"כבד את אביך ואת אמך\" (שמות כ, יא), \u0003יכול מפני שכיבוד האב קודם\u0004 ועדיף \u0003על כיבוד האם? תלמוד לומר: \"איש אמו ואביו תיראו\"\u0004 (ויקרא יט, ג), תחילה האם ואחר כך האב — \u0003מלמד ששניהם שקולין, אבל אמרו חכמים:\u0004 מכל מקום כבוד \u0003האב קודם לאם בכל מקום, מפני שהוא\u0004 (הבן) \u0003ו\u0004גם \u0003אמו חייבין בכבוד אביו.\u0004","\u0003וכן\u0004 הדין \u0003בתלמוד תורה, אם זכה הבן לפני הרב,\u0004 שרוב חכמתו ממנו — \u0003הרב קודם את האב בכל מקום,\u0004 והטעם: \u0003מפני שהוא ואביו חייבין בכבוד רבו,\u0004 שכל אדם חייב בכבודם של חכמים.","אגב ענין זה של כבשים ועיזים מביאים מעשה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבע צווחות צווחה\u0004 ה\u0003עזרה צווחה אחת: הוציאו מיכן\u0004 את \u0003בני עלי\u0004 הכהן, \u0003חפני ופנחס שטימאו את ההיכל\u0004 את המשכן שבשילה במעשיהם (ראה שמואל א ב, יג—כב).","\u0003צווחה שניה: פתחו שערים ויכנס יוחנן בן נדבאי תלמידו של פינקאי וימלא כרסו מקדשי שמים,\u0004 שראוי הוא לכך. \u0003אמרו על בן נדבאי, שהיה אוכל ארבע סאה גוזלות\u0004"],["\u0003בקינוח סעודה,\u0004 לאחר שהיה אוכל עיקר סעודתו. \u0003אמרו\u0004 עליו שכל \u0003ימיו לא היה\u0004 בשר \u0003נותר בעזרה,\u0004 לפי שהיה דואג שייאכל הכל בזמנו.","\u0003צווחה שלישית\u0004 שצווחה העזרה: \u0003שאו שערים ראשיכם ויכנס אלישמע בן פיכאי תלמידו של פנחס\u0004 (בן אלעזר בן אהרן הכהן) \u0003וישמש בכהונה גדולה,\u0004 שהוא ראוי לה.","\u0003צווחה רביעית\u0004 צווחה העזרה: \u0003פתחו שערים והוציאו יששכר איש כפר ברקאי, שמכבד עצמו ומבזה קדשי שמים.\u0004 ומסבירים: \u0003מאי הוי עביד\u0004 \u0005[מה היה עושה]\u0006 שאמרו עליו דבר זה? \u0003הוה כריך שיראי על ידיה והוה עביד\u0004 \u0005[היה כורך משי על ידו והיה עובד]\u0006 \u0003עבודה,\u0004 כדי שלא יתלכלכו ידיו.","\u0003מאי סליקא ליה\u0004 \u0005[מה עלתה לו]?\u0006 מסופר: \u0003ינאי מלכא ומלכתא הוו יתבין\u0004 \u0005[ינאי המלך והמלכה היו יושבים]\u0006 ודנים בענייני מאכל, \u0003מלכא\u0004 \u0005[המלך]\u0006 \u0003אמר: גדיא יאי\u0004 \u0005[הגדי מובחר]\u0006 \u0003ומלכתא\u0004 \u0005[והמלכה]\u0006 \u0003אמרה: אימרא יאי\u0004 \u0005[הכבש מובחר],\u0006 \u0003אמרו\u0004 שניהם: \u0003נשייליה\u0004 \u0005[נשאל]\u0006 את \u0003יששכר איש כפר ברקאי,\u0004 ש\u0003כהן גדול הוא וקים ליה קדירה\u0004 \u0005[והוא מבין במיני תבשיל].\u0006","\u0003שיילוהו\u0004 \u0005[שאלו אותו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי גדיא יאי ייסק לתמידא\u0004 \u0005[אם הגדי היה מובחר,\u0006 כדברי המלך, \u0005היה עולה\u0006 לקרבן \u0005התמיד]\u0006 ולא הכבש (ראה במדבר כח, ד). \u0003בהדי דאמר אחוי בידיה\u0004 \u0005[בזמן שאמר דברים אלה הראה בידו]\u0006 תנועה שיש בה זלזול, \u0003אמר להון מלכא\u0004 \u0005[להם המלך]:\u0006 \u0003הואיל ואחוי בידיה\u0004 \u0005[והראה בידו]\u0006 בתנועה כזו, \u0003קוצו לידיה דימינא\u0004 \u0005[קצצו את יד ימינו].\u0006 \u0003יהיב שוחדא, קציוה לידיה שמאלא\u0004 \u0005[נתן\u0006 יששכר איש כפר ברקאי \u0005שוחד\u0006 לפקידי המלך, \u0005וקצצו את ידו השמאלית]\u0006 במקומה. \u0003שמע מלכא\u0004 \u0005[המלך]\u0006 את המעשה, \u0003אמר: ליקצו נמי לידיה דימינא\u0004 \u0005[שיקצצו גם כן את ידו הימנית],\u0006 ונמצא שהיו שתי ידיו קצוצות. \u0003אמר רב יוסף: בריך רחמנא דשקליה\u0004 \u0005[ברוך הקב\"ה שנטל לו]\u0006 \u0003ליששכר איש כפר ברקאי למטרפסיה\u0004 \u0005[את גמולו],\u0006 שהיה כורך שיראים על ידיו וממעט בכבוד שמים, ונקצצו ידיו.","\u0003אמר רב אשי:\u0004 ועוד, שלא היה חכם \u0003ולא הוה תני ליה דתנן\u0004 \u0005[ולא היה שונה את הדבר ששנינו\u0006 במשנה\u0005]\u0006\u0003: כבשים ק ודמין לעזים בכל מקום\u0004 בתורה, \u0003יכול מפני שמובחרין? תלמוד לומר\u0004 בקרבן החטאת: \"והביא קרבנו שעירת עיזים\" (ויקרא ד, כח), ורק אחר כך: \u0003\"ואם כבש\"\u0004 (שם לב) — \u0003מלמד ששניהן שקולין כאחת.\u0004","\u0003רבינא אמר: אפילו מקרא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קרא, דכתיב\u0004 \u0005[שנאמר]\u0006 בקרבן השלמים: \u0003\"אם כבש\u0004 הוא מקריב\", \u0003\"אם עז\u0004 קרבנו\" (ויקרא ג, ז. שם יב), ומשמע מלשון זו שאיזה שירצה רשאי להקריב. ומסיימים בדבר טוב: \u0003אמר ר' אלעזר אמר ר' חנינא: תלמידי חכמים מרבים שלום בעולם, שנאמר: \"וכל בניך למודי ה' ורב שלום בניך\"\u0004 (ישעיהו נד, יג), ודרשו חכמים: אל תקרא \"בניך\" אלא \"בוניך\", לומר: תלמידי חכמים, שהם בוני התורה, מרבים שלום.","",""]]};
